window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2ce46c17cdf8d8dd"]={"versions": [{"id": "FIG-2ce46c17cdf8d8dd", "releases": ["R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Ausschnitt des AUTOSAR M2-Metamodells (<em>BSW Module Description Template</em>, <code>BswInternalBehavior</code>).\n</li><li><strong>Funktionaler Kontext:</strong> Modellierung des internen Verhaltens von BSW-Modulen (Basic Software) in der AUTOSAR Classic Platform.\n</li><li><strong>Architektur-Zweck:</strong> Definition der Trigger-Kopplung zwischen Modul-Ereignissen (<code>BswEvent</code>) und den ausführbaren C-Funktionen (<code>BswModuleEntity</code>). Bildet die formale Grundlage für die Konfiguration des Schedule Managers (SchM), die OS-Task-Abbildung sowie die Multicore-Allokation von BSW-Funktionen gemäß <em>AUTOSAR BSW Distribution Guide</em>.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Wurzel &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>BswInternalBehavior</code></strong> (Spezialisierung von <code>InternalBehavior</code>): Zentraler Container für die Verhaltensbeschreibung einer BSW-Modulinstanz.\n</li><li><strong><code>«atpVariation»</code></strong>: Kennzeichnet Variationspunkte (AUTOSAR Template Profile). Sowohl Events (<code>+event [0..*]</code>) als auch Entities (<code>+entity [1..*]</code>) können über Pre-Compile- oder Post-Build-Conditions variantenabhängig eingebunden werden.\n</li></ul>\n<h5 class=\"fig-section-h5\">Event-Hierarchie (Generalisierung von <code>AbstractEvent</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>BswEvent</code></strong>: Abstrakte Basisklasse aller BSW-Ereignisse.\n</li><li><strong><code>BswOperationInvokedEvent</code></strong>: Löst die synchrone oder asynchrone Abarbeitung bei Eintreffen eines Operationsaufrufs (Client-Server / API) aus.\n</li><li><strong><code>BswScheduleEvent</code></strong> (<em>kursiv / abstrakt</em>): Basisklasse für alle periodischen oder ereignisgesteuerten Trigger, die über den BSW Scheduler (SchM) in Betriebssystem-Tasks disponiert werden.\n<ul class=\"fig-list\"><li><strong><code>BswTimingEvent</code></strong>: Zyklischer Trigger; spezifiziert über das Attribut <code>period : TimeValue</code> (z. B. für periodische Main-Functions).\n</li><li><strong><code>BswBackgroundEvent</code></strong>: Niedrigstpriorer Trigger zur Ausführung in Leerlaufphasen (Background-Task).\n</li><li><strong><code>BswExternalTriggerOccurredEvent</code></strong>: Getriggert durch externe Hard- oder Peripherie-Interrupts/Trigger.\n</li><li><strong><code>BswInternalTriggerOccurredEvent</code></strong>: BSW-interner Software-Trigger zwischen Modulfunktionen.\n</li><li><strong><code>BswModeSwitchEvent</code></strong>: Zustandsänderungs-Trigger (vom BswM gesteuert); besitzt Attribut <code>activation : ModeActivationKind</code> (<code>ON_ENTRY</code>, <code>ON_EXIT</code>, <code>ON_TRANSITION</code>).\n</li><li><strong><code>BswModeSwitchedAckEvent</code></strong>: Rückmeldung / Acknowledge über einen abgeschlossenen Mode-Switch.\n</li><li><strong><code>BswModeManagerErrorEvent</code></strong>: Fehler-Trigger bei gescheiterten Mode-Transitionen.\n</li><li><strong><code>BswDataReceivedEvent</code></strong>: Trigger bei Verfügbarkeit neuer Kommunikationsdaten (Sender-Receiver).\n</li><li><strong><code>BswAsynchronousServerCallReturnsEvent</code></strong>: Callback-Event bei Fertigstellung eines asynchronen Server-Aufrufs.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Entity-Hierarchie (Generalisierung von <code>ExecutableEntity</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>BswModuleEntity</code></strong>: Abstrakter Basistyp für ausführbaren C-Code eines BSW-Moduls.\n</li><li><strong><code>BswCalledEntity</code></strong>: Repräsentiert direkt/synchron per Funktionsaufruf aufgerufene Modul-APIs.\n<ul class=\"fig-list\"><li>Assoziation: <code>startsOnEvent [1]</code> verweist auf <code>BswOperationInvokedEvent</code>.\n</li></ul>\n</li><li><strong><code>BswSchedulableEntity</code></strong>: Repräsentiert Scheduler-verwaltete C-Funktionen (z. B. <code>&lt;Mod&gt;_MainFunction</code>).\n<ul class=\"fig-list\"><li>Assoziation: <code>startsOnEvent [1]</code> verweist auf <code>BswScheduleEvent</code>.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Synchrone Ausführungspfad (<code>BswCalledEntity</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Ein externer Caller (SWC via RTE oder anderes BSW-Modul) ruft eine BSW-Schnittstelle auf.\n</li><li><strong>Dispatch:</strong> Entspricht semantisch einem <code>BswOperationInvokedEvent</code>.\n</li><li><strong>Kontext:</strong> Der Aufruf wird unmittelbar im Thread/Task-Kontext des Aufrufers synchron ausgeführt (kein Task-Wechsel, sofern sender- und empfängerseitige Partitionen/Cores identisch sind; andernfalls Weiterleitung über Inter-OS-Application- bzw. Inter-Core-Stubs).\n</li></ol>\n<h5 class=\"fig-section-h5\">Scheduler-gesteuerter Ausführungspfad (<code>BswSchedulableEntity</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Trigger-Erzeugung:</strong>\n<ul class=\"fig-list\"><li>Zeitablauf (OS-Counter/Alarm) feuert <code>BswTimingEvent</code>.\n</li><li>Zustandstransition im BswM feuert <code>BswModeSwitchEvent</code>.\n</li><li>Empfang von I-PDUs / Daten feuert <code>BswDataReceivedEvent</code>.\n</li></ul>\n</li><li><strong>SchM-Dispatching:</strong> Der RTE/SchM fängt das Event ab und aktiviert die zugeordnete OS-Task (<code>ActivateTask</code> oder <code>SetEvent</code>).\n</li><li><strong>Execution:</strong> Im Kontext der OS-Task ruft der SchM die konfigurierte C-Funktion der <code>BswSchedulableEntity</code> (<code>&lt;Mod&gt;_MainFunction</code>) auf.\n</li><li><strong>Asynchrone Rückmeldung:</strong> Nach asynchronen Diensten wird <code>BswAsynchronousServerCallReturnsEvent</code> erzeugt, um die Fortsetzung im SchM-Kontext zu triggern.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSWMD-Konfiguration (ARXML):</strong>\n<ul class=\"fig-list\"><li>Für jede Modul-Main-Function (<code>Can_MainFunction_Write</code>, <code>Com_MainFunctionRx</code> etc.) muss zwingend eine <code>BswSchedulableEntity</code> mit passendem <code>BswScheduleEvent</code> (typischerweise <code>BswTimingEvent</code> mit <code>period</code>) deklariert werden.\n</li><li>Standard-Modul-APIs (<code>Can_Write</code>, <code>Com_SendSignal</code>) sind als <code>BswCalledEntity</code> zu modellieren.\n</li></ul>\n</li><li><strong>SchM- und OS-Task-Mapping:</strong>\n<ul class=\"fig-list\"><li>Der RTE/SchM-Generator nutzt <code>startsOnEvent</code>, um <code>BswSchedulableEntities</code> in generierte SchM-Tasks einzubetten.\n</li><li>Unpräzise Perioden (<code>TimeValue</code>) oder unvollständige Mode-Aktivierungen (<code>ModeActivationKind</code>) führen zu Timing-Jitter, Deadline-Verletzungen oder fehlenden Modus-Umschaltungen.\n</li></ul>\n</li><li><strong>Multicore- &amp; BSW-Distribution:</strong>\n<ul class=\"fig-list\"><li><code>BswSchedulableEntities</code> können flexibel auf Cores/OS-Applications verteilt werden.\n</li><li><code>BswCalledEntities</code> erfordern bei Core-übergreifenden Zugriffen zwingend Cross-Core-Mechanismen (z. B. IOC – <em>Inter-OS-Application Communicator</em> oder RPC-Stubs des SchM).\n</li></ul>\n</li><li><strong>Konkurrierender Zugriff &amp; Reentrancy:</strong>\n<ul class=\"fig-list\"><li>Teilt sich eine <code>BswCalledEntity</code> oder <code>BswSchedulableEntity</code> Daten mit anderen Entities, müssen im <code>BswInternalBehavior</code> korrespondierende <code>BswExclusiveArea</code>-Definitionen hinterlegt werden, die der SchM in OS-Interrupt-Sperren (<code>SuspendAllInterrupts</code>) oder Spinlocks auflöst.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-9e6cab765c891833", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Ausschnitt des AUTOSAR M2-Metamodells (<em>BSW Module Description Template</em>, <code>BswInternalBehavior</code>).\n</li><li><strong>Funktionaler Kontext:</strong> Modellierung des internen Verhaltens von BSW-Modulen (Basic Software) in der AUTOSAR Classic Platform.\n</li><li><strong>Architektur-Zweck:</strong> Definition der Trigger-Kopplung zwischen Modul-Ereignissen (<code>BswEvent</code>) und den ausführbaren C-Funktionen (<code>BswModuleEntity</code>). Bildet die formale Grundlage für die Konfiguration des Schedule Managers (SchM), die OS-Task-Abbildung sowie die Multicore-Allokation von BSW-Funktionen gemäß <em>AUTOSAR BSW Distribution Guide</em>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Wurzel &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>BswInternalBehavior</code></strong> (Spezialisierung von <code>InternalBehavior</code>): Zentraler Container für die Verhaltensbeschreibung einer BSW-Modulinstanz.\n</li><li><strong><code>«atpVariation»</code></strong>: Kennzeichnet Variationspunkte (AUTOSAR Template Profile). Sowohl Events (<code>+event [0..*]</code>) als auch Entities (<code>+entity [1..*]</code>) können über Pre-Compile- oder Post-Build-Conditions variantenabhängig eingebunden werden.\n</li></ul>\n<h5 class=\"fig-section-h5\">Event-Hierarchie (Generalisierung von <code>AbstractEvent</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>BswEvent</code></strong>: Abstrakte Basisklasse aller BSW-Ereignisse.\n</li><li><strong><code>BswOperationInvokedEvent</code></strong>: Löst die synchrone oder asynchrone Abarbeitung bei Eintreffen eines Operationsaufrufs (Client-Server / API) aus.\n</li><li><strong><code>BswScheduleEvent</code></strong> (<em>kursiv / abstrakt</em>): Basisklasse für alle periodischen oder ereignisgesteuerten Trigger, die über den BSW Scheduler (SchM) in Betriebssystem-Tasks disponiert werden.\n<ul class=\"fig-list\"><li><strong><code>BswTimingEvent</code></strong>: Zyklischer Trigger; spezifiziert über das Attribut <code>period : TimeValue</code> (z. B. für periodische Main-Functions).\n</li><li><strong><code>BswBackgroundEvent</code></strong>: Niedrigstpriorer Trigger zur Ausführung in Leerlaufphasen (Background-Task).\n</li><li><strong><code>BswExternalTriggerOccurredEvent</code></strong>: Getriggert durch externe Hard- oder Peripherie-Interrupts/Trigger.\n</li><li><strong><code>BswInternalTriggerOccurredEvent</code></strong>: BSW-interner Software-Trigger zwischen Modulfunktionen.\n</li><li><strong><code>BswModeSwitchEvent</code></strong>: Zustandsänderungs-Trigger (vom BswM gesteuert); besitzt Attribut <code>activation : ModeActivationKind</code> (<code>ON_ENTRY</code>, <code>ON_EXIT</code>, <code>ON_TRANSITION</code>).\n</li><li><strong><code>BswModeSwitchedAckEvent</code></strong>: Rückmeldung / Acknowledge über einen abgeschlossenen Mode-Switch.\n</li><li><strong><code>BswModeManagerErrorEvent</code></strong>: Fehler-Trigger bei gescheiterten Mode-Transitionen.\n</li><li><strong><code>BswDataReceivedEvent</code></strong>: Trigger bei Verfügbarkeit neuer Kommunikationsdaten (Sender-Receiver).\n</li><li><strong><code>BswAsynchronousServerCallReturnsEvent</code></strong>: Callback-Event bei Fertigstellung eines asynchronen Server-Aufrufs.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Entity-Hierarchie (Generalisierung von <code>ExecutableEntity</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>BswModuleEntity</code></strong>: Abstrakter Basistyp für ausführbaren C-Code eines BSW-Moduls.\n</li><li><strong><code>BswCalledEntity</code></strong>: Repräsentiert direkt/synchron per Funktionsaufruf aufgerufene Modul-APIs.\n<ul class=\"fig-list\"><li>Assoziation: <code>startsOnEvent [1]</code> verweist auf <code>BswOperationInvokedEvent</code>.\n</li></ul>\n</li><li><strong><code>BswSchedulableEntity</code></strong>: Repräsentiert Scheduler-verwaltete C-Funktionen (z. B. <code>&lt;Mod&gt;_MainFunction</code>).\n<ul class=\"fig-list\"><li>Assoziation: <code>startsOnEvent [1]</code> verweist auf <code>BswScheduleEvent</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Synchrone Ausführungspfad (<code>BswCalledEntity</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Trigger:</strong> Ein externer Caller (SWC via RTE oder anderes BSW-Modul) ruft eine BSW-Schnittstelle auf.\n</li><li><strong>Dispatch:</strong> Entspricht semantisch einem <code>BswOperationInvokedEvent</code>.\n</li><li><strong>Kontext:</strong> Der Aufruf wird unmittelbar im Thread/Task-Kontext des Aufrufers synchron ausgeführt (kein Task-Wechsel, sofern sender- und empfängerseitige Partitionen/Cores identisch sind; andernfalls Weiterleitung über Inter-OS-Application- bzw. Inter-Core-Stubs).\n</li></ol>\n<h5 class=\"fig-section-h5\">Scheduler-gesteuerter Ausführungspfad (<code>BswSchedulableEntity</code>)</h5>\n<ol class=\"fig-list\"><li><strong>Trigger-Erzeugung:</strong>\n<ul class=\"fig-list\"><li>Zeitablauf (OS-Counter/Alarm) feuert <code>BswTimingEvent</code>.\n</li><li>Zustandstransition im BswM feuert <code>BswModeSwitchEvent</code>.\n</li><li>Empfang von I-PDUs / Daten feuert <code>BswDataReceivedEvent</code>.\n</li></ul>\n</li><li><strong>SchM-Dispatching:</strong> Der RTE/SchM fängt das Event ab und aktiviert die zugeordnete OS-Task (<code>ActivateTask</code> oder <code>SetEvent</code>).\n</li><li><strong>Execution:</strong> Im Kontext der OS-Task ruft der SchM die konfigurierte C-Funktion der <code>BswSchedulableEntity</code> (<code>&lt;Mod&gt;_MainFunction</code>) auf.\n</li><li><strong>Asynchrone Rückmeldung:</strong> Nach asynchronen Diensten wird <code>BswAsynchronousServerCallReturnsEvent</code> erzeugt, um die Fortsetzung im SchM-Kontext zu triggern.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSWMD-Konfiguration (ARXML):</strong>\n<ul class=\"fig-list\"><li>Für jede Modul-Main-Function (<code>Can_MainFunction_Write</code>, <code>Com_MainFunctionRx</code> etc.) muss zwingend eine <code>BswSchedulableEntity</code> mit passendem <code>BswScheduleEvent</code> (typischerweise <code>BswTimingEvent</code> mit <code>period</code>) deklariert werden.\n</li><li>Standard-Modul-APIs (<code>Can_Write</code>, <code>Com_SendSignal</code>) sind als <code>BswCalledEntity</code> zu modellieren.\n</li></ul>\n</li><li><strong>SchM- und OS-Task-Mapping:</strong>\n<ul class=\"fig-list\"><li>Der RTE/SchM-Generator nutzt <code>startsOnEvent</code>, um <code>BswSchedulableEntities</code> in generierte SchM-Tasks einzubetten.\n</li><li>Unpräzise Perioden (<code>TimeValue</code>) oder unvollständige Mode-Aktivierungen (<code>ModeActivationKind</code>) führen zu Timing-Jitter, Deadline-Verletzungen oder fehlenden Modus-Umschaltungen.\n</li></ul>\n</li><li><strong>Multicore- &amp; BSW-Distribution:</strong>\n<ul class=\"fig-list\"><li><code>BswSchedulableEntities</code> können flexibel auf Cores/OS-Applications verteilt werden.\n</li><li><code>BswCalledEntities</code> erfordern bei Core-übergreifenden Zugriffen zwingend Cross-Core-Mechanismen (z. B. IOC – <em>Inter-OS-Application Communicator</em> oder RPC-Stubs des SchM).\n</li></ul>\n</li><li><strong>Konkurrierender Zugriff &amp; Reentrancy:</strong>\n<ul class=\"fig-list\"><li>Teilt sich eine <code>BswCalledEntity</code> oder <code>BswSchedulableEntity</code> Daten mit anderen Entities, müssen im <code>BswInternalBehavior</code> korrespondierende <code>BswExclusiveArea</code>-Definitionen hinterlegt werden, die der SchM in OS-Interrupt-Sperren (<code>SuspendAllInterrupts</code>) oder Spinlocks auflöst.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-58a6a4b0bcd76f12", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Ausschnitt des AUTOSAR M2-Metamodells (<em>BSW Module Description Template</em>, <code>BswInternalBehavior</code>).\n</li><li><strong>Funktionaler Kontext:</strong> Modellierung des internen Verhaltens von BSW-Modulen (Basic Software) in der AUTOSAR Classic Platform.\n</li><li><strong>Architektur-Zweck:</strong> Definition der Trigger-Kopplung zwischen Modul-Ereignissen (<code>BswEvent</code>) und den ausführbaren C-Funktionen (<code>BswModuleEntity</code>). Bildet die formale Grundlage für die Konfiguration des Schedule Managers (SchM), die OS-Task-Abbildung sowie die Multicore-Allokation von BSW-Funktionen gemäß <em>AUTOSAR BSW Distribution Guide</em>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Wurzel &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>BswInternalBehavior</code></strong> (Spezialisierung von <code>InternalBehavior</code>): Zentraler Container für die Verhaltensbeschreibung einer BSW-Modulinstanz.\n</li><li><strong><code>«atpVariation,atpSplitable»</code></strong>: Beide Kompositionen (<code>+event [0..*]</code> und <code>+entity [0..*]</code>) sind als variant (<code>«atpVariation»</code>) sowie splitbar über mehrere ARXML-Dateien (<code>«atpSplitable»</code>) deklariert.\n</li><li><strong>Kardinalität <code>+entity [0..*]</code></strong>: Entitäten sind optional; erlaubt leere Verhaltensbeschreibungen oder reine Event-Definitionen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Event-Hierarchie (Generalisierung von <code>AbstractEvent</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>BswEvent</code></strong>: Abstrakte Basisklasse aller BSW-Ereignisse.\n<ul class=\"fig-list\"><li>Assoziation: <code>+startsOnEvent [0..1]</code> verbindet <code>BswEvent</code> direkt mit <code>BswModuleEntity</code>.\n</li></ul>\n</li><li><strong>Direkte Spezialisierungen von <code>BswEvent</code>:</strong>\n<ul class=\"fig-list\"><li><strong><code>BswOperationInvokedEvent</code></strong>: Trigger bei Eintreffen eines Operationsaufrufs (Client-Server / API).\n</li><li><strong><code>BswInterruptEvent</code></strong>: Trigger für Interrupt-Service-Routinen (CAT1 / CAT2 ISRs).\n</li><li><strong><code>BswScheduleEvent</code></strong> (<em>kursiv / abstrakt</em>): Basisklasse für alle Scheduler-verwalteten Trigger.\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>BswScheduleEvent</code>:</strong>\n<ul class=\"fig-list\"><li><strong><code>BswTimingEvent</code></strong>: Zyklischer Trigger; Attribut <code>period : TimeValue [0..1]</code>.\n</li><li><strong><code>BswBackgroundEvent</code></strong>: Trigger für Leerlauf-/Hintergrund-Tasks.\n</li><li><strong><code>BswExternalTriggerOccurredEvent</code></strong>: Trigger durch externe Hardware- oder Peripherie-Ereignisse.\n</li><li><strong><code>BswInternalTriggerOccurredEvent</code></strong>: BSW-interner Software-Trigger zwischen Modulfunktionen.\n</li><li><strong><code>BswModeSwitchEvent</code></strong>: Trigger bei Moduswechseln; Attribut <code>activation : ModeActivationKind [0..1]</code>.\n</li><li><strong><code>BswModeSwitchedAckEvent</code></strong>: Acknowledge-Rückmeldung eines vollzogenen Moduswechsels.\n</li><li><strong><code>BswModeManagerErrorEvent</code></strong>: Fehler-Trigger bei fehlgeschlagenen Modusübergängen.\n</li><li><strong><code>BswDataReceivedEvent</code></strong>: Trigger bei Eingang neuer Kommunikationsdaten.\n</li><li><strong><code>BswAsynchronousServerCallReturnsEvent</code></strong>: Callback-Trigger bei Rückkehr eines asynchronen Server-Calls.\n</li><li><strong><code>BswOsTaskExecutionEvent</code></strong>: Trigger gekoppelt an die Aktivierung/Abarbeitung einer OS-Task.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Entity-Hierarchie (Generalisierung von <code>ExecutableEntity</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>BswModuleEntity</code></strong>: Abstrakter Basistyp für ausführbaren C-Code eines BSW-Moduls; Ziel der <code>+startsOnEvent [0..1]</code>-Assoziation von <code>BswEvent</code>.\n</li><li><strong><code>BswCalledEntity</code></strong>: Repräsentiert direkt/synchron per API aufgerufene Modulfunktionen.\n</li><li><strong><code>BswSchedulableEntity</code></strong>: Repräsentiert Scheduler-verwaltete C-Funktionen (z. B. Main-Functions).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Generisches Event-zu-Entity-Dispatching</h5>\n<ol class=\"fig-list\"><li><strong>Triggerung:</strong> Ein beliebiges <code>BswEvent</code> tritt auf.\n</li><li><strong>Kopplung via <code>startsOnEvent</code>:</strong> Über die generalisierte Assoziation <code>+startsOnEvent [0..1]</code> wird direkt die zugehörige <code>BswModuleEntity</code> aktiviert.\n</li></ol>\n<h5 class=\"fig-section-h5\">Ausführungspfade nach Entitätstyp</h5>\n<ul class=\"fig-list\"><li><strong>Synchrone Ausführung (<code>BswCalledEntity</code>):</strong> Typischerweise ausgelöst durch <code>BswOperationInvokedEvent</code>; läuft unmittelbar im Thread-/Task-Kontext des Aufrufers ab.\n</li><li><strong>Scheduler-basierte Ausführung (<code>BswSchedulableEntity</code>):</strong> Ausgelöst durch Spezialisierungen von <code>BswScheduleEvent</code> (z. B. <code>BswTimingEvent</code>, <code>BswDataReceivedEvent</code>, <code>BswModeSwitchEvent</code> oder <code>BswOsTaskExecutionEvent</code>); Zuweisung und Aktivierung erfolgen über den Schedule Manager (SchM) in einer OS-Task.\n</li><li><strong>Interrupt-Abarbeitung (<code>BswInterruptEvent</code>):</strong> Ausführung im ISR-Kontext (CAT1/CAT2) bei Hardware-Ereignissen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Refaktorisierung:</strong> Die Assoziation <code>startsOnEvent</code> wurde von den konkreten Subtypen (<code>BswCalledEntity</code>, <code>BswSchedulableEntity</code>) auf die abstrakten Basisebenen <code>BswEvent</code> und <code>BswModuleEntity</code> gehoben. Dadurch wird die Trigger-Beziehung metamodellweit vereinheitlicht und die Kardinalität an der Entity auf <code>0..1</code> gesetzt.\n</li><li><strong>ARXML-Splitting (<code>«atpSplitable»</code>):</strong> Die Stereotypisierung der Kompositionen <code>+event</code> und <code>+entity</code> mit <code>«atpSplitable»</code> ermöglicht die Aufteilung von BSW-Verhaltensbeschreibungen über separate ARXML-Dateien, was die Arbeitsteiligkeit bei Multi-Core- und Multi-Partner-Projekten wesentlich unterstützt.\n</li><li><strong>Entfall der Entitäts-Mindestanzahl:</strong> Die Änderung der unteren Kardinalität von <code>entity</code> von <code>1..*</code> auf <code>0..*</code> erlaubt valide <code>BswInternalBehavior</code>-Beschreibungen ohne vorab definierte Entitäten (z. B. in frühen Phasen der Systemdefinition).\n</li><li><strong>Erweiterte Event-Typen:</strong> Mit <code>BswInterruptEvent</code> und <code>BswOsTaskExecutionEvent</code> können ISR-Trigger und dedizierte OS-Task-Aktivierungen im BSW-Modell formal abgebildet und konfiguriert werden.\n</li><li><strong>Attribut-Kardinalitäten:</strong> Die Attribute <code>period</code> (<code>BswTimingEvent</code>) und <code>activation</code> (<code>BswModeSwitchEvent</code>) tragen nun explizit die Multiplizität <code>[0..1]</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5fcc33901e7f0997", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Ausschnitt des AUTOSAR M2-Metamodells (<em>BSW Module Description Template</em>, <code>BswInternalBehavior</code>).\n</li><li><strong>Funktionaler Kontext:</strong> Modellierung des internen Verhaltens von BSW-Modulen (Basic Software) in der AUTOSAR Classic Platform.\n</li><li><strong>Architektur-Zweck:</strong> Definition der Trigger-Kopplung zwischen Modul-Ereignissen (<code>BswEvent</code>) und den ausführbaren C-Funktionen (<code>BswModuleEntity</code>). Bildet die formale Grundlage für die Konfiguration des Schedule Managers (SchM), die OS-Task-Abbildung sowie die Multicore-Allokation von BSW-Funktionen gemäß <em>AUTOSAR BSW Distribution Guide</em>.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Wurzel &amp; Stereotypen</h5>\n<ul class=\"fig-list\"><li><strong><code>BswInternalBehavior</code></strong> (Spezialisierung von <code>InternalBehavior</code>): Zentraler Container für die Verhaltensbeschreibung einer BSW-Modulinstanz.\n</li><li><strong><code>«atpVariation,atpSplitable»</code></strong>: Beide Kompositionen (<code>+event [0..*]</code> und <code>+entity [0..*]</code>) sind als variant (<code>«atpVariation»</code>) sowie splitbar über mehrere ARXML-Dateien (<code>«atpSplitable»</code>) deklariert.\n</li><li><strong>Kardinalität <code>+entity [0..*]</code></strong>: Entitäten sind optional; erlaubt leere Verhaltensbeschreibungen oder reine Event-Definitionen.\n</li></ul>\n<h5 class=\"fig-section-h5\">Event-Hierarchie (Generalisierung von <code>AbstractEvent</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>BswEvent</code></strong>: Abstrakte Basisklasse aller BSW-Ereignisse.\n<ul class=\"fig-list\"><li>Assoziation: <code>+startsOnEvent [0..1]</code> verbindet <code>BswEvent</code> direkt mit <code>BswModuleEntity</code>.\n</li></ul>\n</li><li><strong>Direkte Spezialisierungen von <code>BswEvent</code>:</strong>\n<ul class=\"fig-list\"><li><strong><code>BswOperationInvokedEvent</code></strong>: Trigger bei Eintreffen eines Operationsaufrufs (Client-Server / API).\n</li><li><strong><code>BswInterruptEvent</code></strong>: Trigger für Interrupt-Service-Routinen (CAT1 / CAT2 ISRs).\n</li><li><strong><code>BswScheduleEvent</code></strong> (<em>kursiv / abstrakt</em>): Basisklasse für alle Scheduler-verwalteten Trigger.\n</li></ul>\n</li><li><strong>Spezialisierungen von <code>BswScheduleEvent</code>:</strong>\n<ul class=\"fig-list\"><li><strong><code>BswTimingEvent</code></strong>: Zyklischer Trigger; Attribut <code>period : TimeValue [0..1]</code>.\n</li><li><strong><code>BswBackgroundEvent</code></strong>: Trigger für Leerlauf-/Hintergrund-Tasks.\n</li><li><strong><code>BswExternalTriggerOccurredEvent</code></strong>: Trigger durch externe Hardware- oder Peripherie-Ereignisse.\n</li><li><strong><code>BswInternalTriggerOccurredEvent</code></strong>: BSW-interner Software-Trigger zwischen Modulfunktionen.\n</li><li><strong><code>BswModeSwitchEvent</code></strong>: Trigger bei Moduswechseln; Attribut <code>activation : ModeActivationKind [0..1]</code>.\n</li><li><strong><code>BswModeSwitchedAckEvent</code></strong>: Acknowledge-Rückmeldung eines vollzogenen Moduswechsels.\n</li><li><strong><code>BswModeManagerErrorEvent</code></strong>: Fehler-Trigger bei fehlgeschlagenen Modusübergängen.\n</li><li><strong><code>BswDataReceivedEvent</code></strong>: Trigger bei Eingang neuer Kommunikationsdaten.\n</li><li><strong><code>BswAsynchronousServerCallReturnsEvent</code></strong>: Callback-Trigger bei Rückkehr eines asynchronen Server-Calls.\n</li><li><strong><code>BswOsTaskExecutionEvent</code></strong>: Trigger gekoppelt an die Aktivierung/Abarbeitung einer OS-Task.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Entity-Hierarchie (Generalisierung von <code>ExecutableEntity</code>)</h5>\n<ul class=\"fig-list\"><li><strong><code>BswModuleEntity</code></strong>: Abstrakter Basistyp für ausführbaren C-Code eines BSW-Moduls; Ziel der <code>+startsOnEvent [0..1]</code>-Assoziation von <code>BswEvent</code>.\n</li><li><strong><code>BswCalledEntity</code></strong>: Repräsentiert direkt/synchron per API aufgerufene Modulfunktionen.\n</li><li><strong><code>BswSchedulableEntity</code></strong>: Repräsentiert Scheduler-verwaltete C-Funktionen (z. B. Main-Functions).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Generisches Event-zu-Entity-Dispatching</h5>\n<ol class=\"fig-list\"><li><strong>Triggerung:</strong> Ein beliebiges <code>BswEvent</code> tritt auf.\n</li><li><strong>Kopplung via <code>startsOnEvent</code>:</strong> Über die generalisierte Assoziation <code>+startsOnEvent [0..1]</code> wird direkt die zugehörige <code>BswModuleEntity</code> aktiviert.\n</li></ol>\n<h5 class=\"fig-section-h5\">Ausführungspfade nach Entitätstyp</h5>\n<ul class=\"fig-list\"><li><strong>Synchrone Ausführung (<code>BswCalledEntity</code>):</strong> Typischerweise ausgelöst durch <code>BswOperationInvokedEvent</code>; läuft unmittelbar im Thread-/Task-Kontext des Aufrufers ab.\n</li><li><strong>Scheduler-basierte Ausführung (<code>BswSchedulableEntity</code>):</strong> Ausgelöst durch Spezialisierungen von <code>BswScheduleEvent</code> (z. B. <code>BswTimingEvent</code>, <code>BswDataReceivedEvent</code>, <code>BswModeSwitchEvent</code> oder <code>BswOsTaskExecutionEvent</code>); Zuweisung und Aktivierung erfolgen über den Schedule Manager (SchM) in einer OS-Task.\n</li><li><strong>Interrupt-Abarbeitung (<code>BswInterruptEvent</code>):</strong> Ausführung im ISR-Kontext (CAT1/CAT2) bei Hardware-Ereignissen.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Metamodell-Refaktorisierung:</strong> Die Assoziation <code>startsOnEvent</code> wurde von den konkreten Subtypen (<code>BswCalledEntity</code>, <code>BswSchedulableEntity</code>) auf die abstrakten Basisebenen <code>BswEvent</code> und <code>BswModuleEntity</code> gehoben. Dadurch wird die Trigger-Beziehung metamodellweit vereinheitlicht und die Kardinalität an der Entity auf <code>0..1</code> gesetzt.\n</li><li><strong>ARXML-Splitting (<code>«atpSplitable»</code>):</strong> Die Stereotypisierung der Kompositionen <code>+event</code> und <code>+entity</code> mit <code>«atpSplitable»</code> ermöglicht die Aufteilung von BSW-Verhaltensbeschreibungen über separate ARXML-Dateien, was die Arbeitsteiligkeit bei Multi-Core- und Multi-Partner-Projekten wesentlich unterstützt.\n</li><li><strong>Entfall der Entitäts-Mindestanzahl:</strong> Die Änderung der unteren Kardinalität von <code>entity</code> von <code>1..*</code> auf <code>0..*</code> erlaubt valide <code>BswInternalBehavior</code>-Beschreibungen ohne vorab definierte Entitäten (z. B. in frühen Phasen der Systemdefinition).\n</li><li><strong>Erweiterte Event-Typen:</strong> Mit <code>BswInterruptEvent</code> und <code>BswOsTaskExecutionEvent</code> können ISR-Trigger und dedizierte OS-Task-Aktivierungen im BSW-Modell formal abgebildet und konfiguriert werden.\n</li><li><strong>Attribut-Kardinalitäten:</strong> Die Attribute <code>period</code> (<code>BswTimingEvent</code>) und <code>activation</code> (<code>BswModeSwitchEvent</code>) tragen nun explizit die Multiplizität <code>[0..1]</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-2ce46c17cdf8d8dd", "to": "FIG-9e6cab765c891833", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-9e6cab765c891833", "to": "FIG-58a6a4b0bcd76f12", "fr": "R19-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>BswInternalBehavior</code>: Stereotyp beider Kompositionen (<code>+event</code> und <code>+entity</code>) von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code> erweitert.\n</li><li><code>BswInternalBehavior</code>: Kardinalität der Komposition <code>+entity</code> von <code>1..*</code> auf <code>0..*</code> gelockert.\n</li><li><code>BswEvent</code> / <code>BswModuleEntity</code>: Die Assoziation <code>startsOnEvent</code> wurde von den konkreten Subtypen auf die Basisebene gehoben und verbindet nun <code>BswEvent</code> mit <code>BswModuleEntity</code> als gerichtete Assoziation <code>+startsOnEvent</code> mit Kardinalität <code>0..1</code> (vorher getrennte Assoziationen <code>startsOnEvent [1]</code> an <code>BswCalledEntity</code> und <code>BswSchedulableEntity</code>).\n</li><li><code>BswEvent</code>: Neue Spezialisierung <code>BswInterruptEvent</code> ergänzt.\n</li><li><code>BswScheduleEvent</code>: Neue Spezialisierung <code>BswOsTaskExecutionEvent</code> ergänzt.\n</li><li><code>BswTimingEvent</code>: Attribut <code>period : TimeValue</code> explizit mit Kardinalität <code>[0..1]</code> versehen.\n</li><li><code>BswModeSwitchEvent</code>: Attribut <code>activation : ModeActivationKind</code> explizit mit Kardinalität <code>[0..1]</code> versehen.\n</li><li>Layout: Zweispaltige Neuordnung der Spezialisierungen von <code>BswScheduleEvent</code>.\n</li></ul>"}, {"from": "FIG-58a6a4b0bcd76f12", "to": "FIG-5fcc33901e7f0997", "fr": "R23-11", "tr": "R24-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
